<?php
namespace App\Http\Controllers;
use App\Models\Customer;use Illuminate\Http\Request;
class CustomerController extends Controller {private function manager(Request $r):void{abort_unless($r->user()?->isManager(),403);}public function index(Request $r){$this->manager($r);$customers=Customer::when($r->q,fn($q,$term)=>$q->where(fn($x)=>$x->where('name','like','%'.$term.'%')->orWhere('email','like','%'.$term.'%')->orWhere('phone','like','%'.$term.'%')))->orderBy('name')->paginate(15)->withQueryString();return view('customers.index',compact('customers'));}public function store(Request $r){$this->manager($r);$data=$r->validate(['name'=>'required|string|max:150','email'=>'nullable|email|max:190','phone'=>'nullable|string|max:50','address'=>'nullable|string|max:1000','status'=>'required|in:active,inactive','notes'=>'nullable|string|max:2000']);Customer::create($data);return back()->with('success','Customer created successfully.');}public function update(Request $r,Customer $customer){$this->manager($r);$data=$r->validate(['name'=>'required|string|max:150','email'=>'nullable|email|max:190','phone'=>'nullable|string|max:50','address'=>'nullable|string|max:1000','status'=>'required|in:active,inactive','notes'=>'nullable|string|max:2000']);$customer->update($data);return back()->with('success','Customer updated successfully.');}}
